package ama.transcript;
import ama.config.ConfigArchiveSource;import ama.contract.ConfigArchiveContracts.Ref;import ama.contract.IdentityContracts.Actor;import ama.contract.MinutesContracts.*;import ama.contract.TaskContracts.SubjectRef;import java.util.*;import java.util.function.Supplier;import org.springframework.jdbc.core.JdbcTemplate;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Later immutable settings changes; first-only initialization remains Task9-owned. */
public final class JdbcMinutesSettingsCommands {
 private final JdbcTranscriptAuthority authority;private final Supplier<ConfigArchiveSource.Snapshot> archives;private final String pin;private final Ref prompt,model;private final TranscriptAcquisitionBudget limits;private final JdbcMinutesCommandReceipts receipts;private final JdbcTemplate j;
 public JdbcMinutesSettingsCommands(JdbcTranscriptAuthority authority,Supplier<ConfigArchiveSource.Snapshot> archives,String pin,Ref prompt,Ref model,TranscriptAcquisitionBudget limits){this.authority=Objects.requireNonNull(authority);this.archives=Objects.requireNonNull(archives);hash(pin);this.pin=pin;this.prompt=Objects.requireNonNull(prompt);this.model=Objects.requireNonNull(model);this.limits=Objects.requireNonNull(limits);receipts=new JdbcMinutesCommandReceipts(authority.dataSource(),authority.transactionRunner(),authority.savedAccess());j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);}
 public record Exclusion(String locatorId,String category,String reason){public Exclusion{uuid(locatorId);if(category==null||!Set.of("INTERNAL_BUSINESS_DATA","POLITICAL_SENSITIVE").contains(category))throw new ama.contract.TranscriptContracts.Failure(422,"INVALID_SENSITIVITY_CATEGORY");if(reason!=null)scalars(reason);}}
 private record Plan(MinutesGraphCapture.Graph graph,String result,FullRow revision,List<FullRow> members){}
 public Map<String,Object> replaceExclusions(Actor actor,String meeting,String key,long expected,String source,List<Exclusion> items,String trace){uuid(source);return change(actor,meeting,key,expected,false,source,items,trace);}
 public Map<String,Object> selectTemplate(Actor actor,String meeting,String key,long expected,String revision,String trace){uuid(revision);return change(actor,meeting,key,expected,true,revision,List.of(),trace);}
 private Map<String,Object> change(Actor actor,String meeting,String key,long expected,boolean template,String source,List<Exclusion> items,String trace){
  JdbcMinutesFactsReader.independent();uuid(trace);var normalized=new ArrayList<>(Objects.requireNonNull(items));normalized.sort(Comparator.comparing(Exclusion::locatorId).thenComparing(Exclusion::category));var unique=new HashSet<String>();for(var item:normalized)if(!unique.add(item.locatorId()+"/"+item.category()))throw new ama.contract.TranscriptContracts.Failure(422,"DUPLICATE_EXCLUSION");String operation=template?"MINUTES_TEMPLATE":"MINUTES_EXCLUSIONS";var semantic=new ArrayList<String>();semantic.add(source);for(var item:normalized)Collections.addAll(semantic,item.locatorId(),item.category(),item.reason());var identity=JdbcMinutesCommandReceipts.identity(actor,meeting,operation,key,expected,semantic.toArray(String[]::new));var replay=receipts.lookup(actor,meeting,identity);if(replay.isPresent())return replay.orElseThrow();
  var budget=limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);MinutesGraphDiscovery.Discovery declaration=null;Plan planned=null;RuntimeException error=null;
  try{declaration=MinutesGraphDiscovery.withPending(authority.dataSource(),MinutesGraphDiscovery.discover(authority.dataSource(),meeting,template?"SETTINGS_TEMPLATE":"SETTINGS_EXCLUSIONS",template?source:null,limits,authority.readBudget()),limits.tasks(),budget);declaration=MinutesGraphDiscovery.guarded(authority,actor,declaration,budget);JdbcMinutesFactsReader.charge(declaration,budget);var declared=declaration;var graph=authority.transactionRunner().required(()->{var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,declared);var cap=authority.minutesScope(gate,actor,meeting);var captured=MinutesGraphCapture.captureCurrent(authority,cap,gate,actor,declared,budget);writable(captured,expected,template,source);return captured;});var facts=new JdbcMinutesFactsReader(authority,archives,pin,limits).prepare(graph,budget);
   if(template){var selected=JdbcMinutesFactsReader.one(graph,Table.TEMPLATE_REVISION,source);String owner=selected.nullableString("owner_id");if(owner!=null&&!owner.equals(actor.enterpriseId()))throw new ama.access.MeetingAccess.AccessDeniedException();var installed=ama.minutes.MinutesCatalogAdmission.capture(archives.get(),prompt,model,authority.readBudget());require(pin.equals(installed.indexSha()),PROFILE_UNAVAILABLE);for(var raw:installed.archives()){var bytes=raw.bytes();budget.capture(bytes.length,bytes.length,bytes.length,16);}if(owner==null)require(source.equals(installed.defaultTemplateRevisionId()),CAPABILITY_UNAVAILABLE);require(selected.number("theme_count")==7&&ama.minutes.ControlledMinutesTemplateInstaller.THEMES.equals(selected.string("themes")),CAPABILITY_UNAVAILABLE);planned=new Plan(graph,source,null,List.of());}
   else{var set=graph.discovery().root().get("element_set_id");var allowed=new HashSet<String>();var current=JdbcMinutesFactsReader.one(graph,Table.TRANSCRIPT_CONFIRMATION,(String)graph.discovery().root().get("transcript_confirmation_id"));for(var detection:JdbcMinutesFactsReader.rows(graph,Table.SENSITIVE_DETECTION))if(set!=null&&set.equals(detection.string("set_id")))for(var member:JdbcMinutesFactsReader.rows(graph,Table.SENSITIVE_DETECTION_SOURCE))if(detection.string("id").equals(member.string("detection_id"))){var locator=JdbcMinutesFactsReader.one(graph,Table.SOURCE_LOCATOR,member.string("locator_id"));require("TRANSCRIPT".equals(locator.string("kind"))&&current.string("revision_id").equals(locator.string("transcript_revision_id")),CAPABILITY_UNAVAILABLE);allowed.add(member.string("locator_id")+"/"+detection.string("category"));}for(var item:normalized)if(!allowed.contains(item.locatorId()+"/"+item.category()))throw new ama.contract.TranscriptContracts.Failure(422,"CURRENT_DETECTION_SOURCE_REQUIRED");
    String id=UUID.randomUUID().toString();long revision=MinutesHistorySlots.next(graph,"exclusion_revision",1);String now=java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSSSSS'Z'").format(java.time.LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));var row=new FullRow(Table.EXCLUSION_REVISION,List.of(cell(id),cell(meeting),cell(revision),cell(now)));var members=new ArrayList<FullRow>();for(var item:normalized){if(item.reason()!=null)budget.text(ama.canonical.CanonicalValueCodec.utf8Length(item.reason(),()->false),item.reason().codePointCount(0,item.reason().length()),item.reason().length(),8,true);budget.row(4);members.add(new FullRow(Table.SENSITIVE_EXCLUSION,List.of(cell(id),cell(item.locatorId()),cell(item.category()),item.reason()==null?new NullCell():cell(item.reason()))));}planned=new Plan(graph,id,row,List.copyOf(members));}
  }catch(RuntimeException failure){if(Thread.currentThread().isInterrupted()||failure instanceof Failure f&&f.code()==CANCELLED)throw failure;error=failure;}
  final var selected=declaration;final var plan=planned;final var failed=error;return authority.transactionRunner().required(()->{var stored=receipts.claim(actor,meeting,identity);var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,selected);JdbcMinutesCommandReceipts.match(stored);MinutesDeferredPreparation.beforeReplay(failed);if(stored.result()!=null)return receipts.restore(meeting,identity,stored,true);JdbcMinutesCommandReceipts.requireRevision(j,meeting,expected);if(failed!=null)throw failed;var cap=authority.minutesScope(gate,actor,meeting);var fresh=MinutesGraphCapture.captureCurrent(authority,cap,gate,actor,selected,budget);require(fresh.equals(plan.graph()),PROVENANCE_UNAVAILABLE);writable(fresh,expected,template,source);authority.claimMinutesWrite(cap,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.SETTINGS,plan);authority.requireMinutesInvocation(cap,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.SETTINGS,plan);
   if(!template){var row=plan.revision();require(j.update("INSERT INTO exclusion_revision(id,meeting_id,revision,created_at) VALUES (?,?,?,?)",plan.result(),meeting,row.number("revision"),java.time.LocalDateTime.ofInstant(java.time.Instant.parse(row.string("created_at")),java.time.ZoneOffset.UTC))==1,PROVENANCE_UNAVAILABLE);for(var member:plan.members())require(j.update("INSERT INTO sensitive_exclusion(revision_id,locator_id,category,reason) VALUES (?,?,?,?)",plan.result(),member.string("locator_id"),member.string("category"),member.nullableString("reason"))==1,PROVENANCE_UNAVAILABLE);var read=new SavedTranscriptRows(j,budget,authority.readBudget().maxManifestBytes());require(read.rows(Table.EXCLUSION_REVISION,"id=?","id",1,true,plan.result()).equals(List.of(row)),PROVENANCE_UNAVAILABLE);require(read.rows(Table.SENSITIVE_EXCLUSION,"revision_id=?","locator_id,category",plan.members().size()+1,true,plan.result()).equals(plan.members()),PROVENANCE_UNAVAILABLE);}
   var fences=new ama.task.JdbcSubjectFences(authority.dataSource(),Set.of("MEETING"));var subject=fences.lock(new SubjectRef("MEETING",meeting),false).orElseThrow(()->fail(PROVENANCE_UNAVAILABLE));require(subject.businessVersion()==expected,PROVENANCE_UNAVAILABLE);String pointer=template?"template_revision_id":"exclusion_revision_id";require(j.update("UPDATE meeting SET "+pointer+"=?,revision=?,needs_generation=1,final_confirmation_id=NULL,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND revision=? AND cancel_epoch=?",plan.result(),expected+1,meeting,expected,subject.cancelEpoch())==1,PROVENANCE_UNAVAILABLE);require(j.queryForObject("SELECT "+pointer+" FROM meeting WHERE id=?",String.class,meeting).equals(plan.result()),PROVENANCE_UNAVAILABLE);require(j.update("UPDATE meeting_search_projection SET meeting_revision=? WHERE meeting_id=?",expected+1,meeting)==1,PROVENANCE_UNAVAILABLE);fences.advance(subject,expected+1,subject.cancelEpoch(),false);authority.finishMinutesGraphTransition(cap,gate,actor,fresh,expected+1);receipts.accepted(identity,plan.result());var response=receipts.restore(meeting,identity,new JdbcMinutesCommandReceipts.Stored(plan.result(),200,true),false);String event=template?"MINUTES_TEMPLATE_SELECTED":"MINUTES_EXCLUSIONS_SAVED";new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(actor.enterpriseId(),event,meeting,expected+1,"SUCCEEDED",trace,java.time.Instant.now()));var outbox=new ama.task.JdbcOutbox(authority.dataSource(),new MinutesEventReferences(authority.dataSource()).validators());outbox.append(new ama.contract.OutboxContracts.EventDraft(event,null,new SubjectRef("MEETING",meeting),expected+1,new ama.contract.OutboxContracts.Reference(template?"TEMPLATE_REVISION":"EXCLUSION_REVISION",plan.result())));outbox.flush();return response;});
 }
 private static void writable(MinutesGraphCapture.Graph graph,long expected,boolean template,String source){var root=graph.discovery().root();if(((Number)root.get("revision")).longValue()!=expected)throw new ama.contract.TranscriptContracts.Failure(409,"REVISION_CONFLICT");if(expected>=Long.MAX_VALUE-1)throw new ama.contract.TranscriptContracts.Failure(409,"REVISION_EXHAUSTED");require(root.get("template_revision_id")!=null&&root.get("exclusion_revision_id")!=null&&root.get("transcript_confirmation_id")!=null,CAPABILITY_UNAVAILABLE);if(!template&&!source.equals(root.get("exclusion_revision_id")))throw new ama.contract.TranscriptContracts.Failure(409,"EXCLUSION_REVISION_CONFLICT");var guard=graph.auxiliary().getOrDefault("meeting_minutes_editor_guard",List.of());if(guard.size()!=1||((Number)guard.getFirst().get("intent_epoch")).longValue()<=0)throw new ama.contract.TranscriptContracts.Failure(409,"EDITOR_INTENT_REQUIRED");require(((Number)root.get("ever_published")).intValue()==0&&"ACTIVE".equals(root.get("lifecycle"))&&"ACTIVE".equals(root.get("governance_state"))&&!"PUBLISHED".equals(root.get("stage"))&&root.get("material_snapshot_id")==null&&((Number)root.get("materials_pending")).intValue()==0,CAPABILITY_UNAVAILABLE);}
}
